text.insert:
name: count-commits
description: Record each recent commit as a repo.commits metric
nodes:
  - id: count
    runtime: bun
    script: |
      const log = Bun.spawnSync(['git', 'log', '--since=30 days ago', '--format=%H %cI']);
      if (log.exitCode !== 0) throw new Error(log.stderr.toString());
      const metrics = log.stdout.toString().trim().split('\n').filter(Boolean).map(line => {
        const [sha, at] = line.split(' ');
        return { name: 'repo.commits', kind: 'count', unit: 'commits', value: 1, subject: sha, at };
      });
      console.log(JSON.stringify({ metrics }));
    output_format:
      type: object
      required: [metrics]
      properties:
        metrics: { type: array }

 for every project,
and a project's Metrics tab for its own records, over the last 7, 30 or 90 days
(

{
  "names": {
    "factory.prs_merged": "PRs merged",
    "factory.tests_unprotective": "Useless tests"
  },
  "cards": [
    {
      "shape": "count",
      "title": "PRs merged",
      "metric": "factory.prs_merged",
      "breakdown": [{ "metric": "factory.prs_opened", "label": "opened" }]
    },
    {
      "shape": "ratio",
      "title": "Useless tests",
      "numerator": "factory.tests_unprotective",
      "denominator": "factory.tests_added",
      "denominator_label": "new tests",
      "calibration": {
        "metric": "factory.tests_unprotective_judge_catch_rate",
        "label": "judge catches",
        "rough_below": 0.8
      }
    },
    {
      "shape": "cost_per",
      "title": "Cost per PR",
      "metric": "factory.prs_merged",
      "cost_of": "factory.prs_opened"
    }
  ]
}
